import React, { useState } from 'react';

const Roadmap = () => {
  const [roadmapItems, setRoadmapItems] = useState([]);

  const addRoadmapItem = (title, description) => {
    const newItem = { id: Date.now(), title, description };
    setRoadmapItems([...roadmapItems, newItem]);
  };

  const removeRoadmapItem = (id) => {
    setRoadmapItems(roadmapItems.filter(item => item.id !== id));
  };

  return (
    <div>
      <form>
        <input type="text" placeholder="Title" />
        <input type="text" placeholder="Description" />
        <button type="submit">Add Item</button>
      </form>
      <ul>
        {roadmapItems.map(item => (
          <li key={item.id}>
            <strong>{item.title}</strong>: {item.description}
            <button onClick={() => removeRoadmapItem(item.id)}>Remove</button>
          </li>
        ))}
      </ul>
    </div>
  );
};

